<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">Citizen dashboard</span><h1>Hello, <?=e($u['full_name'])?></h1><p>Track your submissions and updates.</p><form method="post" action="<?=url('logout')?>"><?=csrf_field()?><button class="text-link button-link">Sign out</button></form></header><section class="wrap dashboard-grid"><div class="content-card"><h2>My issues</h2><?php foreach($issues as $i):?><a class="record-row" href="<?=$i['moderation_status']==='approved'?url('issues/'.$i['slug']):'#'?>"><strong><?=e($i['title'])?></strong><span><?=e($i['moderation_status'])?> · <?=e(str_replace('_',' ',$i['progress_status']))?></span></a><?php endforeach;?><?php if(!$issues):?><p>No issues submitted.</p><?php endif;?><a class="pill pill-dark" href="<?=url('issues/create')?>">Raise an issue</a></div><div class="content-card"><h2>My discussions</h2><?php foreach($discussions as $d):?><div class="record-row"><strong><?=e($d['title'])?></strong><span><?=e($d['status'])?></span></div><?php endforeach;?><?php if(!$discussions):?><p>No discussions started.</p><?php endif;?><a class="pill pill-light" href="<?=url('discussions/create')?>">Start a discussion</a></div><div class="content-card"><h2>Notifications</h2><?php foreach($notifications as $n):?><div class="record-row"><strong><?=e($n['title'])?></strong><span><?=e($n['message'])?></span></div><?php endforeach;?><?php if(!$notifications):?><p>No notifications.</p><?php endif;?></div></section></div>
